from datetime import datetime

def check_cancellation_status(event_date, is_cancelled, cancellation_date=None, required_days_notice=7):
    current_date = datetime.now()
    event_datetime = datetime.strptime(event_date, "%Y-%m-%d")

    sufficient_notice = None
    if is_cancelled and cancellation_date:
        cancel_datetime = datetime.strptime(cancellation_date, "%Y-%m-%d")
        days_difference = (event_datetime - cancel_datetime).days
        sufficient_notice = days_difference >= required_days_notice

    if is_cancelled:
        return {"status": "cancelled", "sufficient_notice": sufficient_notice}
    elif event_datetime < current_date:
        return {"status": "past", "sufficient_notice": None}
    else:
        return {"status": "scheduled", "sufficient_notice": None}
```

